const assert=require('node:assert/strict');const fs=require('node:fs');const vm=require('node:vm');const bank=JSON.parse(fs.readFileSync('data/daily-test-starter.json'));const js=fs.readFileSync('assets/daily-test.js','utf8');new vm.Script(js);for(const [exam,subjects,n] of [['NEET',['Physics','Chemistry','Botany','Zoology'],15],['JEE',['Physics','Chemistry','Mathematics'],20]]){let selected=exam;const els=new Map();function el(){return {style:{},children:[],append(...a){this.children.push(...a)},replaceChildren(...a){this.children=a},addEventListener(){},setAttribute(){},scrollIntoView(){}}}const get=id=>{if(!els.has(id))els.set(id,el());return els.get(id)};const radios=[{value:exam,addEventListener(){}}];const ctx={document:{getElementById:get,createElement:el,querySelector:s=>s.includes(':checked')?{value:selected}:get(s),querySelectorAll:()=>radios},fetch:async()=>({ok:true,json:async()=>bank}),setInterval:()=>1,clearInterval(){},confirm:()=>true,Date,Math};vm.createContext(ctx);vm.runInContext(js,ctx);const button=get('subjectStarts').children.at(-1);assert.equal(button.textContent,'Start '+exam+' Test');(async()=>{button.onclick();await new Promise(r=>setImmediate(r));assert.equal(get('examPanel').hidden,false);assert.match(get('position').textContent,/Question 1 of 60/);assert.equal(get('nav').children.length,subjects.length);for(const section of get('nav').children)assert.equal(section.children[1].children.length,n);assert.equal(get('clock').textContent,subjects.length*30+':00');get('submit').onclick();assert.equal(get('results').children[1].textContent,'0 / 240');assert.match(get('results').children[2].textContent,/60 skipped/);console.log(exam+' combined test passed')})().catch(e=>{console.error(e);process.exitCode=1})}